1	package com.loja.checkout.web;
2	
3	import com.loja.checkout.clube.CatalogoDoClube;
4	import com.loja.checkout.clube.NivelClube;
5	import com.loja.checkout.cupom.CatalogoDeCupons;
6	import com.loja.checkout.cupom.ContextoCupom;
7	import com.loja.checkout.cupom.Cupom;
8	import com.loja.checkout.cupom.SemCupom;
9	import com.loja.checkout.dominio.CodigoErro;
10	import com.loja.checkout.dominio.Dinheiro;
11	import com.loja.checkout.dominio.ItemPedido;
12	import com.loja.checkout.dominio.PedidoRecusadoException;
13	import com.loja.checkout.dominio.Regiao;
14	import com.loja.checkout.entrega.CatalogoDeEntregas;
15	import com.loja.checkout.entrega.Frete;
16	import com.loja.checkout.entrega.ModalidadeEntrega;
17	import com.loja.checkout.pagamento.CatalogoDePagamentos;
18	import com.loja.checkout.pagamento.FormaPagamento;
19	import com.loja.checkout.pagamento.ResultadoPagamento;
20	import java.math.BigDecimal;
21	import java.util.List;
22	import java.util.Objects;
23	import org.springframework.stereotype.Service;
24	
25	/**
26	 * Sabe a ordem do cálculo e a ordem das validações. Não sabe nada de nenhuma
27	 * modalidade, cupom, nível ou forma de pagamento em particular.
28	 */
29	@Service
30	public class CalculadoraResumo {
31	
32	    private static final int PARCELAS_PADRAO = 1;
33	
34	    private final CatalogoDeEntregas entregas;
35	    private final CatalogoDeCupons cupons;
36	    private final CatalogoDoClube clube;
37	    private final CatalogoDePagamentos pagamentos;
38	
39	    public CalculadoraResumo(CatalogoDeEntregas entregas, CatalogoDeCupons cupons, CatalogoDoClube clube,
40	            CatalogoDePagamentos pagamentos) {
41	        this.entregas = entregas;
42	        this.cupons = cupons;
43	        this.clube = clube;
44	        this.pagamentos = pagamentos;
45	    }
46	
47	    public ResumoResponse calcular(PedidoRequest pedido) {
48	        List<ItemPedido> itens = itensValidos(pedido);
49	        BigDecimal subtotalProdutos = Dinheiro.centavos(somar(itens, ItemPedido::total));
50	        BigDecimal pesoKg = somar(itens, ItemPedido::peso);
51	
52	        NivelClube nivel = clube.buscar(pedido.nivelClube())
53	                .orElseThrow(() -> recusar(CodigoErro.NIVEL_CLUBE_INVALIDO));
54	        Regiao regiao = Regiao.porNome(pedido.regiao())
55	                .orElseThrow(() -> recusar(CodigoErro.REGIAO_INVALIDA));
56	
57	        ModalidadeEntrega modalidade = entregas.buscar(pedido.modalidadeEntrega())
58	                .orElseThrow(() -> recusar(CodigoErro.MODALIDADE_INVALIDA));
59	        if (!modalidade.atende(pesoKg)) {
60	            throw recusar(CodigoErro.MODALIDADE_INDISPONIVEL);
61	        }
62	        Frete frete = modalidade.calcular(pesoKg);
63	        BigDecimal valorFrete = nivel.freteGratis() ? Dinheiro.ZERO : Dinheiro.centavos(frete.valor());
64	
65	        Cupom cupom = escolherCupom(pedido.cupom());
66	        ContextoCupom contexto = new ContextoCupom(itens, subtotalProdutos, valorFrete);
67	        if (!cupom.aplicavel(contexto)) {
68	            throw recusar(CodigoErro.CUPOM_NAO_APLICAVEL);
69	        }
70	        BigDecimal descontoCupom = Dinheiro.centavos(cupom.desconto(contexto));
71	
72	        BigDecimal seguro = regiao.seguro(subtotalProdutos);
73	        BigDecimal totalPedido = Dinheiro.centavos(
74	                subtotalProdutos.subtract(descontoCupom).add(valorFrete).add(seguro));
75	
76	        FormaPagamento forma = pagamentos.buscar(pedido.formaPagamento())
77	                .orElseThrow(() -> recusar(CodigoErro.FORMA_PAGAMENTO_INVALIDA));
78	        int parcelas = Objects.requireNonNullElse(pedido.parcelas(), PARCELAS_PADRAO);
79	        if (!forma.aceitaParcelas(parcelas)) {
80	            throw recusar(CodigoErro.PARCELAMENTO_INVALIDO);
81	        }
82	        if (!forma.atende(totalPedido)) {
83	            throw recusar(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
84	        }
85	        ResultadoPagamento pagamento = forma.calcular(totalPedido, parcelas);
86	
87	        return new ResumoResponse(
88	                subtotalProdutos,
89	                descontoCupom,
90	                valorFrete,
91	                frete.prazoDias(),
92	                seguro,
93	                Dinheiro.centavos(pagamento.totalFinal().subtract(totalPedido)),
94	                pagamento.totalFinal(),
95	                parcelas,
96	                pagamento.valorParcela(),
97	                nivel.credito(subtotalProdutos),
98	                nivel.brinde(subtotalProdutos));
99	    }
100	
101	    private List<ItemPedido> itensValidos(PedidoRequest pedido) {
102	        if (pedido == null || pedido.itens() == null || pedido.itens().isEmpty()) {
103	            throw recusar(CodigoErro.PEDIDO_INVALIDO);
104	        }
105	        return pedido.itens().stream().map(this::itemValido).toList();
106	    }
107	
108	    private ItemPedido itemValido(PedidoRequest.ItemRequest item) {
109	        if (item == null || !positivo(item.precoUnitario()) || !positivo(item.pesoKg())
110	                || item.quantidade() == null || item.quantidade() <= 0) {
111	            throw recusar(CodigoErro.PEDIDO_INVALIDO);
112	        }
113	        return new ItemPedido(item.nome(), item.precoUnitario(), item.quantidade(), item.pesoKg());
114	    }
115	
116	    private boolean positivo(BigDecimal valor) {
117	        return valor != null && valor.compareTo(BigDecimal.ZERO) > 0;
118	    }
119	
120	    private Cupom escolherCupom(String codigo) {
121	        if (codigo == null || codigo.isBlank()) {
122	            return SemCupom.INSTANCIA;
123	        }
124	        return cupons.buscar(codigo).orElseThrow(() -> recusar(CodigoErro.CUPOM_INVALIDO));
125	    }
126	
127	    private BigDecimal somar(List<ItemPedido> itens, java.util.function.Function<ItemPedido, BigDecimal> parcela) {
128	        return itens.stream().map(parcela).reduce(BigDecimal.ZERO, BigDecimal::add);
129	    }
130	
131	    private PedidoRecusadoException recusar(CodigoErro codigo) {
132	        return new PedidoRecusadoException(codigo);
133	    }
134	}
