1	package com.loja.checkout.dominio;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	/**
7	 * Arredondamento de dinheiro: centavos, meio para o par. Igual em toda etapa
8	 * do cálculo, por isso mora num lugar só.
9	 */
10	public final class Dinheiro {
11	
12	    public static final BigDecimal ZERO = centavos(BigDecimal.ZERO);
13	
14	    private Dinheiro() {
15	    }
16	
17	    public static BigDecimal centavos(BigDecimal valor) {
18	        return valor.setScale(2, RoundingMode.HALF_EVEN);
19	    }
20	
21	    public static BigDecimal percentual(BigDecimal valor, BigDecimal taxa) {
22	        return centavos(valor.multiply(taxa));
23	    }
24	}
