1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.dominio.Dinheiro;
4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	import java.math.RoundingMode;
7	import org.springframework.stereotype.Component;
8	
9	@Component
10	public class PagamentoCartao implements FormaPagamento {
11	
12	    private static final int MAXIMO_PARCELAS = 12;
13	    private static final int MAXIMO_PARCELAS_SEM_JUROS = 3;
14	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
15	    private static final MathContext PRECISAO = MathContext.DECIMAL128;
16	
17	    @Override
18	    public String codigo() {
19	        return "CARTAO";
20	    }
21	
22	    @Override
23	    public boolean aceitaParcelas(int parcelas) {
24	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
25	    }
26	
27	    @Override
28	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
29	        if (parcelas <= MAXIMO_PARCELAS_SEM_JUROS) {
30	            return semJuros(totalPedido, parcelas);
31	        }
32	        return comJuros(totalPedido, parcelas);
33	    }
34	
35	    private ResultadoPagamento semJuros(BigDecimal totalPedido, int parcelas) {
36	        BigDecimal valorParcela = totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
37	        return new ResultadoPagamento(Dinheiro.centavos(totalPedido), valorParcela);
38	    }
39	
40	    /** Tabela Price: parcela = total × taxa ÷ (1 − (1 + taxa)^−parcelas). */
41	    private ResultadoPagamento comJuros(BigDecimal totalPedido, int parcelas) {
42	        BigDecimal um = BigDecimal.ONE;
43	        BigDecimal fator = um.subtract(um.divide(um.add(TAXA_MENSAL).pow(parcelas, PRECISAO), PRECISAO));
44	        BigDecimal valorParcela = Dinheiro.centavos(
45	                totalPedido.multiply(TAXA_MENSAL, PRECISAO).divide(fator, PRECISAO));
46	        BigDecimal totalFinal = Dinheiro.centavos(valorParcela.multiply(BigDecimal.valueOf(parcelas)));
47	        return new ResultadoPagamento(totalFinal, valorParcela);
48	    }
49	}
