import java.math.*;
public class Calc {
  public static void main(String[] a){
    MathContext mc = MathContext.DECIMAL128;
    BigDecimal t = new BigDecimal("302.09"), i = new BigDecimal("0.0199"), um = BigDecimal.ONE;
    for (int n : new int[]{4,6}) {
      BigDecimal fator = um.subtract(um.divide(um.add(i).pow(n, mc), mc));
      BigDecimal p = t.multiply(i, mc).divide(fator, mc).setScale(2, RoundingMode.HALF_EVEN);
      System.out.println(n + "x parcela=" + p + " total=" + p.multiply(BigDecimal.valueOf(n)).setScale(2, RoundingMode.HALF_EVEN));
    }
  }
}
